{
  "groups": [
    {
      "group_id": "low_rate_shock_vulnerable",
      "rule": "origination_year >= 2020 and origination_year <= 2021 and rate_type == 'fixed' and mortgage_rate_pct < 3.0",
      "rationale": "Borrowers who locked in record-low rates during the pandemic face the largest payment spikes upon renewal and represent a high flight risk for competitive refinancing."
    },
    {
      "group_id": "distressed_variable_holders",
      "rule": "rate_type == 'variable' and credit_score_band in ['below_600', '600_659']",
      "rationale": "Variable rate holders with lower credit scores are experiencing compounded pressure from rising interest costs and restricted borrowing capacity."
    },
    {
      "group_id": "high_debt_family_burden",
      "rule": "n_children >= 2 and adjusted_family_net_income_cad < 75000 and mortgage_payment_monthly_cad > 2000",
      "rationale": "Families with multiple children and limited net income face acute household cash flow constraints that make them hypersensitive to mortgage payment increases."
    },
    {
      "group_id": "uninsured_equity_correction_risk",
      "rule": "insured_flag == False and property_value_cad > 600000 and credit_utilization_pct > 40",
      "rationale": "Uninsured borrowers in high-value properties are most exposed to the current housing market correction and may face equity challenges if their loan-to-value ratio has shifted."
    },
    {
      "group_id": "prime_advisor_reliant",
      "rule": "has_advisor == True and credit_score_band == '720_plus' and mortgage_balance_cad > 400000",
      "rationale": "High-credit borrowers with established advisor relationships are likely to leverage their strong standing to negotiate better renewal terms or switch lenders."
    },
    {
      "group_id": "liquidity_constrained_renters",
      "rule": "occupancy_type == 'rental' and has_savings == False and td_liquid_deposits_cad < 1000",
      "rationale": "Investors or owners of rental properties with minimal liquid buffers are susceptible to changing interest costs given their dependence on rental income for coverage."
    },
    {
      "group_id": "stable_long_tenure_veterans",
      "rule": "td_tenure_months > 90 and credit_score_band == '720_plus' and employment_status == 'employed'",
      "rationale": "Long-tenured borrowers with strong credit and stable employment are the most predictable segment and have the highest likelihood of remaining with the incumbent lender."
    },
    {
      "group_id": "transitional_life_event_impacted",
      "rule": "life_event_6m == True and life_event_type != 'none'",
      "rationale": "Borrowers experiencing significant life transitions like job changes or relocations are in a state of financial flux and require proactive outreach to prevent churn during renewal."
    }
  ]
}
